-- PT122-S4-Q12. Approved 2026-10-01.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT122-S4-Q12$batch02$ AND q.stimulus=$batch02$Politician: The huge amounts of money earned by oil companies elicit the suspicion that the regulations designed to prevent collusion need to be tightened. But just the opposite is true. If the regulations designed to prevent collusion are not excessively burdensome, then oil companies will make profits sufficient to motivate the very risky investments associated with exploration that must be made if society is to have adequate oil supplies. But recent data show that the oil industry’s profits are not the highest among all industries. Clearly, the regulatory burden on oil companies has become excessive.$batch02$ AND q.prompt=$batch02$The reasoning in the politician's argument is most vulnerable to criticism on the grounds that the argument$batch02$ AND q.correct_choice=$batch02$A$batch02$) THEN RAISE EXCEPTION 'Question changed: PT122-S4-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch02$PT122-S4-Q12$batch02$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S4-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT122-S4-Q12$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$The regulatory burden on oil companies is excessive.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Not excessively burdensome → profits sufficient to motivate risky exploration. Oil profits are not the highest of any industry.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$The contrapositive is valid: profits *not* sufficient → regulations excessive. So the politician needs "profits not sufficient." What the data give us is "profits not the highest." Those are different. Profits can fall short of first place and still be plenty to fund risky exploration. The second-best paid job in a company can still pay the rent. The argument works only if "sufficient" requires "highest."$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the hidden link: sufficient profits must be the highest profits.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT122-S4-Q12$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$To get from "not the highest" to "not sufficient," the politician must assume sufficient profits have to be the highest among all industries. Nothing justifies that. Negate it (sufficient profits need not be the highest) and the conclusion no longer follows.$batch02$), ($batch02$B$batch02$, $batch02$The politician does not criticize oil companies at all. The argument defends them from tighter regulation.$batch02$), ($batch02$C$batch02$, $batch02$The argument is conditional, not causal. It does not infer a cause from two things occurring together.$batch02$), ($batch02$D$batch02$, $batch02$The politician has actual data: profits are not the highest. That is evidence, not an absence of evidence. The problem is what the data are taken to show.$batch02$), ($batch02$E$batch02$, $batch02$The data concern the whole oil industry compared with other industries. No single example is generalized.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT122-S4-Q12$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
